<script lang="ts">import { directoryFeature } from '@fex-design/core/upload/features/directory'; import { uploadFeature } from '@fex-design/core/upload/features/upload'; import { UploadRoot, UploadTrigger, createUpload } from '@fex-design/svelte/primitive/upload'; import Button from '@fex-design/svelte/ui/button'; import { uploadBody, uploadServerUrl } from './api'; import DemoList from './demo-list.svelte'; import DemoSection from './demo-section.svelte'; const upload = createUpload({ autoUpload: false, features: [directoryFeature(), uploadFeature({ request: ({ file, signal, onProgress }) => uploadBody(`${uploadServerUrl}/upload`, file, { fileName: file.webkitRelativePath || file.name, signal, onProgress }) })] })</script>
<DemoSection title="文件夹上传" description="directoryFeature 将隐藏文件选择器切换为目录模式，并在请求中保留每个文件的 webkitRelativePath。"><UploadRoot controller={upload}><UploadTrigger>{#snippet children(value)}<Button {...value.props}>选择文件夹</Button>{/snippet}</UploadTrigger><DemoList /></UploadRoot></DemoSection>
